import{_ as e,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"자주 묻는 질문","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ko/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ko/faq/"}],["meta",{"property":"og:title","content":"자주 묻는 질문 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"와일즈, 라이즈와 선브레이크, 월드와 아이스본의 몬스터 헌터 자료와 방어구 세트 검색."}]]},"headers":[],"relativePath":"ko/faq/index.md","filePath":"ko/faq/index.md"}'),i={name:"ko/faq/index.md"};function n(l,a,h,p,s,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="자주-묻는-질문" tabindex="-1">자주 묻는 질문 <a class="header-anchor" href="#자주-묻는-질문" aria-label="Permalink to &quot;자주 묻는 질문&quot;">​</a></h1><h2 id="어떤-게임을-지원하나요" tabindex="-1">어떤 게임을 지원하나요? <a class="header-anchor" href="#어떤-게임을-지원하나요" aria-label="Permalink to &quot;어떤 게임을 지원하나요?&quot;">​</a></h2><p>와일즈, 라이즈＋선브레이크, 월드＋아이스본을 지원합니다. 각 게임의 자료와 시스템은 별도로 관리되며 홈에서 게임을 선택할 수 있습니다.</p><h2 id="어디에서-다운로드하나요" tabindex="-1">어디에서 다운로드하나요? <a class="header-anchor" href="#어디에서-다운로드하나요" aria-label="Permalink to &quot;어디에서 다운로드하나요?&quot;">​</a></h2><p>Android 버전은 <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, HarmonyOS 버전은 <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>에서 제공됩니다. iOS 버전은 출시 준비 중입니다. <a href="./../#download">다운로드</a>에서 링크를 확인하세요. 이용 가능 여부는 지역과 기기에 따라 다릅니다.</p><h2 id="오프라인에서도-사용할-수-있나요" tabindex="-1">오프라인에서도 사용할 수 있나요? <a class="header-anchor" href="#오프라인에서도-사용할-수-있나요" aria-label="Permalink to &quot;오프라인에서도 사용할 수 있나요?&quot;">​</a></h2><p>자료가 앱에 포함되어 있어 도감 조회, 검색, 즐겨찾기와 방어구 검색을 기기에서 실행합니다. 외부 사이트 방문과 업데이트 다운로드에는 인터넷이 필요합니다.</p><h2 id="방어구-검색은-어떻게-사용하나요" tabindex="-1">방어구 검색은 어떻게 사용하나요? <a class="header-anchor" href="#방어구-검색은-어떻게-사용하나요" aria-label="Permalink to &quot;방어구 검색은 어떻게 사용하나요?&quot;">​</a></h2><p>목표 스킬과 레벨을 지정하고 장비를 고정하거나 제외하며 보유 장식주 수량을 반영합니다. 라이즈에서는 보유 호석과 괴이 연성 방어구도 사용할 수 있습니다. 결과는 자료와 조건에 따라 달라지며 대미지 계산 기능은 포함하지 않습니다.</p><h2 id="어떤-언어를-지원하나요" tabindex="-1">어떤 언어를 지원하나요? <a class="header-anchor" href="#어떤-언어를-지원하나요" aria-label="Permalink to &quot;어떤 언어를 지원하나요?&quot;">​</a></h2><p>앱은 14개 언어를 지원합니다. 번역이 없는 일부 게임 문구는 영어로 표시될 수 있습니다. 라틴 아메리카 스페인어 문구가 없으면 스페인 스페인어를 먼저 확인한 뒤 영어를 사용합니다.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="공식-앱인가요" tabindex="-1">공식 앱인가요? <a class="header-anchor" href="#공식-앱인가요" aria-label="Permalink to &quot;공식 앱인가요?&quot;">​</a></h2><p>아닙니다. 팬이 독립적으로 만든 앱이며 CAPCOM과 관련이 없고 승인이나 후원을 받지 않았습니다. Monster Hunter의 이미지와 데이터는 CAPCOM Co., Ltd.의 소유입니다.</p>',14)])])}const u=e(i,[["render",n]]);export{f as __pageData,u as default};
